import React, { useState } from "react";

export default function UploadArea({ category, onSuccess, onError }) {
  const [dragging, setDragging] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleDrop = (e) => {
    e.preventDefault();
    setDragging(false);
    const files = e.dataTransfer.files;
    upload(files);
  };

  const upload = (files) => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      if (files.length > 0) onSuccess();
      else onError();
    }, 1500);
  };

  return (
    <div
      className={`upload-area ${dragging ? "dragging" : ""}`}
      onDragOver={(e) => {
        e.preventDefault();
        setDragging(true);
      }}
      onDragLeave={() => setDragging(false)}
      onDrop={handleDrop}
    >
      {loading ? (
        <p>Uploading...</p>
      ) : (
        <>
          <p>Drag & Drop photos in {category}</p>
          <input type="file" multiple onChange={(e) => upload(e.target.files)} />
        </>
      )}
    </div>
  );
}
